local ForgeAshPanMaker = {}
local PRODUCTS = {
    iron_forgeashpan = { name = "Železni pepelnik za kovaško peč", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni pepelnik za kovaško peč za kovace." },
    bronze_forgeashpan = { name = "Bronast pepelnik za kovaško peč", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast pepelnik za kovaško peč za kovace." },
    silver_forgeashpan = { name = "Srebrn pepelnik za kovaško peč", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn pepelnik za kovaško peč za kovace." },
    gilded_forgeashpan = { name = "Pozlačen pepelnik za kovaško peč", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen pepelnik za kovaško peč za kovace." },
    jewel_set_forgeashpan = { name = "Draguljast pepelnik za kovaško peč", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast pepelnik za kovaško peč za kovace." },
    royal_sovereign_forgeashpan = { name = "Kraljevski suveren pepelnik za kovaško peč", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren pepelnik za kovaško peč z biseri za krono." },
}
local BUILDINGS = {
    forgeashpan_workshop = { name = "Forgeashpan delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    forgeashpan_house = { name = "Forgeashpan hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_forgeashpan_atelier = { name = "Mojstrski forgeashpan atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_forgeashpan_palace = { name = "Suverena forgeashpan palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ForgeAshPanMaker.ironStock=16; ForgeAshPanMaker.bronzeStock=12; ForgeAshPanMaker.woodStock=12; ForgeAshPanMaker.leatherStock=8; ForgeAshPanMaker.silverStock=8; ForgeAshPanMaker.goldStock=6; ForgeAshPanMaker.jewelStock=4; ForgeAshPanMaker.pearlStock=4
ForgeAshPanMaker.productStock = {}; ForgeAshPanMaker.buildings = {}; ForgeAshPanMaker.maker = nil; ForgeAshPanMaker.activeMaking = {}; ForgeAshPanMaker.totalProducts = 0; ForgeAshPanMaker.dayTimer = 0
function ForgeAshPanMaker.init() ForgeAshPanMaker.ironStock=16; ForgeAshPanMaker.bronzeStock=12; ForgeAshPanMaker.woodStock=12; ForgeAshPanMaker.leatherStock=8; ForgeAshPanMaker.silverStock=8; ForgeAshPanMaker.goldStock=6; ForgeAshPanMaker.jewelStock=4; ForgeAshPanMaker.pearlStock=4; ForgeAshPanMaker.productStock={}; ForgeAshPanMaker.buildings={}; ForgeAshPanMaker.maker=nil; ForgeAshPanMaker.activeMaking={}; ForgeAshPanMaker.totalProducts=0; ForgeAshPanMaker.dayTimer=0; print("[ForgeAshPanMaker] Royal Forge Ash Pan Maker System initialized (6 products, 4 buildings)") end
function ForgeAshPanMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ForgeAshPanMaker.maker={name=n or ("Pepelnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pepelnikar najet: %s (spretnost: %d)",ForgeAshPanMaker.maker.name,s),"success") end; return true end
function ForgeAshPanMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ForgeAshPanMaker.build(id) local ok,e=ForgeAshPanMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ForgeAshPanMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ForgeAshPanMaker.getQualityBonus() local b=0; for _,bd in ipairs(ForgeAshPanMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ForgeAshPanMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ForgeAshPanMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ForgeAshPanMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ForgeAshPanMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ForgeAshPanMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ForgeAshPanMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ForgeAshPanMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ForgeAshPanMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ForgeAshPanMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ForgeAshPanMaker.buildings==0 then return false,"Potrebna pepelska delavnica" end; if not ForgeAshPanMaker.maker then return false,"Potreben pepelnikar" end; return true end
function ForgeAshPanMaker.make(pt,qty) qty=qty or 1; local ok,e=ForgeAshPanMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ForgeAshPanMaker.ironStock=ForgeAshPanMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ForgeAshPanMaker.bronzeStock=ForgeAshPanMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ForgeAshPanMaker.woodStock=ForgeAshPanMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ForgeAshPanMaker.leatherStock=ForgeAshPanMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ForgeAshPanMaker.silverStock=ForgeAshPanMaker.silverStock-d.silverCost*qty end; if d.goldCost then ForgeAshPanMaker.goldStock=ForgeAshPanMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ForgeAshPanMaker.jewelStock=ForgeAshPanMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ForgeAshPanMaker.pearlStock=ForgeAshPanMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ForgeAshPanMaker.maker then t=math.max(1,t-math.floor(ForgeAshPanMaker.maker.skill/13)) end; table.insert(ForgeAshPanMaker.activeMaking,{id="forgeashpan_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ForgeAshPanMaker.completeMaking(m) local q=1.0+(ForgeAshPanMaker.getQualityBonus()/100); if ForgeAshPanMaker.maker then q=q+(ForgeAshPanMaker.maker.skill/140) end; q=math.min(2.5,q); ForgeAshPanMaker.productStock[m.productType]=(ForgeAshPanMaker.productStock[m.productType] or 0)+m.quantity; ForgeAshPanMaker.totalProducts=ForgeAshPanMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ForgeAshPanMaker.maker then ForgeAshPanMaker.maker.itemsMade=ForgeAshPanMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ForgeAshPanMaker.maker.skill=math.min(100,ForgeAshPanMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pepelnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"forgeashpan.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ForgeAshPanMaker.update(dt) if not _G.state then return end; ForgeAshPanMaker.dayTimer=ForgeAshPanMaker.dayTimer+dt; if ForgeAshPanMaker.dayTimer>=30 then ForgeAshPanMaker.dayTimer=0; for i=#ForgeAshPanMaker.activeMaking,1,-1 do local m=ForgeAshPanMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ForgeAshPanMaker.completeMaking(m); table.remove(ForgeAshPanMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ForgeAshPanMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ForgeAshPanMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ForgeAshPanMaker.getStats() return {ironStock=ForgeAshPanMaker.ironStock,bronzeStock=ForgeAshPanMaker.bronzeStock,woodStock=ForgeAshPanMaker.woodStock,leatherStock=ForgeAshPanMaker.leatherStock,silverStock=ForgeAshPanMaker.silverStock,goldStock=ForgeAshPanMaker.goldStock,jewelStock=ForgeAshPanMaker.jewelStock,pearlStock=ForgeAshPanMaker.pearlStock,productStock=ForgeAshPanMaker.productStock,numBuildings=#ForgeAshPanMaker.buildings,hasMaker=ForgeAshPanMaker.maker~=nil,makerName=ForgeAshPanMaker.maker and ForgeAshPanMaker.maker.name or "—",makerSkill=ForgeAshPanMaker.maker and ForgeAshPanMaker.maker.skill or 0,activeMaking=#ForgeAshPanMaker.activeMaking,totalProducts=ForgeAshPanMaker.totalProducts} end
return ForgeAshPanMaker
